-- Supabase DEV only: member password reset by company administrator.
-- Token is generated by Cloudflare Functions; only SHA-256 hash is stored.
CREATE TABLE IF NOT EXISTS private.m360_member_password_resets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  company_id uuid NOT NULL REFERENCES public.m360_companies(id) ON DELETE CASCADE,
  target_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  requested_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  CONSTRAINT m360_member_password_resets_expiry CHECK (expires_at > created_at)
);
CREATE INDEX IF NOT EXISTS m360_member_password_resets_target_idx
  ON private.m360_member_password_resets(target_user_id, expires_at DESC);

CREATE TABLE IF NOT EXISTS private.m360_member_security_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id uuid NOT NULL REFERENCES public.m360_companies(id) ON DELETE CASCADE,
  actor_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  target_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  event_type text NOT NULL CHECK (event_type IN ('password_reset_requested','password_reset_completed')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS m360_member_security_events_company_idx
  ON private.m360_member_security_events(company_id, created_at DESC);
ALTER TABLE private.m360_member_password_resets ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.m360_member_security_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.m360_member_password_resets FROM PUBLIC, anon, authenticated;
REVOKE ALL ON private.m360_member_security_events FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA private TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON private.m360_member_password_resets TO service_role;
GRANT SELECT, INSERT ON private.m360_member_security_events TO service_role;

CREATE OR REPLACE FUNCTION public.issue_m360_member_password_reset(
 p_company_id uuid,p_actor_user_id uuid,p_target_user_id uuid,p_token_hash text
) RETURNS boolean LANGUAGE plpgsql
SET search_path=pg_catalog,public,private,auth,pg_temp AS $$
BEGIN
 IF p_token_hash !~ '^[0-9a-f]{64}$' OR p_actor_user_id=p_target_user_id THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.m360_company_members WHERE company_id=p_company_id AND user_id=p_actor_user_id AND role='admin' AND status='active') THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.m360_company_members WHERE company_id=p_company_id AND user_id=p_target_user_id AND role='member' AND status='active') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM private.m360_platform_roles WHERE user_id=p_target_user_id AND role='platform_admin' AND status='active') THEN RETURN false; END IF;
 UPDATE private.m360_member_password_resets SET consumed_at=now() WHERE target_user_id=p_target_user_id AND consumed_at IS NULL;
 INSERT INTO private.m360_member_password_resets(token_hash,company_id,target_user_id,requested_by,expires_at)
 VALUES(p_token_hash,p_company_id,p_target_user_id,p_actor_user_id,now()+interval '30 minutes');
 INSERT INTO private.m360_member_security_events(company_id,actor_user_id,target_user_id,event_type)
 VALUES(p_company_id,p_actor_user_id,p_target_user_id,'password_reset_requested');
 RETURN true;
END; $$;

CREATE OR REPLACE FUNCTION public.consume_m360_member_password_reset(p_token_hash text)
RETURNS TABLE(user_id uuid,company_id uuid,requested_by uuid)
LANGUAGE plpgsql SET search_path=pg_catalog,public,private,auth,pg_temp AS $$
DECLARE v_reset private.m360_member_password_resets%ROWTYPE;
BEGIN
 IF p_token_hash !~ '^[0-9a-f]{64}$' THEN RETURN; END IF;
 UPDATE private.m360_member_password_resets r SET consumed_at=now()
 WHERE r.token_hash=p_token_hash AND r.consumed_at IS NULL AND r.expires_at>now()
 AND EXISTS(SELECT 1 FROM public.m360_company_members m WHERE m.company_id=r.company_id AND m.user_id=r.target_user_id AND m.status='active')
 RETURNING r.* INTO v_reset;
 IF NOT FOUND THEN RETURN; END IF;
 INSERT INTO private.m360_member_security_events(company_id,actor_user_id,target_user_id,event_type)
 VALUES(v_reset.company_id,v_reset.requested_by,v_reset.target_user_id,'password_reset_completed');
 RETURN QUERY SELECT v_reset.target_user_id,v_reset.company_id,v_reset.requested_by;
END; $$;
REVOKE ALL ON FUNCTION public.issue_m360_member_password_reset(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.consume_m360_member_password_reset(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.issue_m360_member_password_reset(uuid,uuid,uuid,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.consume_m360_member_password_reset(text) TO service_role;
